 $scale=[Math]::Min(240.0/$src.Width,240.0/$src.Height);$dw=[Math]::Round($src.Width*$scale);$dh=[Math]::Round($src.Height*$scale);$dx=[Math]::Round((256-$dw)/2);$dy=248-$dh;$scaled=[Drawing.Bitmap]::new(256,256,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($scaled);$g.Clear([Drawing.Color]::Transparent);$g.CompositingMode=[Drawing.Drawing2D.CompositingMode]::SourceCopy;$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.DrawImage($src,[Drawing.Rectangle]::new($dx,$dy,$dw,$dh),[Drawing.Rectangle]::new(0,0,$src.Width,$src.Height),[Drawing.GraphicsUnit]::Pixel);$g.Dispose();$src.Dispose()
