 for($y=0;$y-lt256;$y++){for($x=0;$x-lt256;$x++){$p=$scaled.GetPixel($x,$y);if($hasAlpha){$a=if($p.A-le159){0}elseif($p.A-ge240){255}else{CB(($p.A-159)*255/81)}}else{$mn=[Math]::Min($p.R,[Math]::Min($p.G,$p.B));$mx=[Math]::Max($p.R,[Math]::Max($p.G,$p.B));$a=255;if($mn-ge230){$a=0}elseif($mn-ge178-and($mx-$mn)-lt30){$a=CB((230-$mn)/52*255)}};if($a-eq0){$albedo.SetPixel($x,$y,[Drawing.Color]::Transparent);$normal.SetPixel($x,$y,[Drawing.Color]::Transparent);$emission.SetPixel($x,$y,[Drawing.Color]::Transparent);$mask.SetPixel($x,$y,[Drawing.Color]::Transparent);$ao.SetPixel($x,$y,[Drawing.Color]::Transparent);continue};$lit=$name-eq"mineral_a"-and$p.R-gt80-and$p.B-gt65-and$p.R-gt$p.G*1.3;if($lit){$peak=[Math]::Max($p.R,$p.B);$f=[Math]::Min(1,105/[Math]::Max(1,$peak));$albedo.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,(CB($p.R*$f)),(CB($p.G*$f)),(CB($p.B*$f))));$emission.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,$p.R,$p.G,$p.B))}else{$albedo.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,$p.R,$p.G,$p.B));$emission.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,0,0,0))};$steel=($p.B-$p.R-gt5)-and($p.B-$p.G-lt45);$metal=if($steel){185}else{35};$gloss=if($steel){58}elseif($lit){115}else{20};$mask.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,$metal,$gloss,0));$v=CB(194+[Math]::Min(61,(Lum $p)*.42));$ao.SetPixel($x,$y,[Drawing.Color]::FromArgb($a,$v,$v,$v))}}
